                    zeroRows[r] = true;
                    zeroCols[c] = true;
                }
            }
        }
        for (int r = 0; r < rows; ++r)
        {
            for (int c = 0; c < cols; ++c)
            {
                if (zeroRows[r] || zeroCols[c])
                    matrix[r][c] = 0;
            }
        }
    }
}

