public class Solution
{
    public bool DeleteMiddle(LinkedListNode? target)
    {
        if (target == null || target.Next == null)
            return false;
        LinkedListNode? successor = target.Next;
        target.Value = successor!.Value;
        target.Next = successor!.Next;
        return true;
    }
}

