      while (!left.empty() || !right.empty() || forwardCarry != 0) {
        int total = forwardCarry;
        if (!left.empty()) {
          total += left.back();
          left.pop_back();
        }
        if (!right.empty()) {
          total += right.back();
          right.pop_back();
        }
