class Solution {
 public:
  LinkedListNode* FindLoopEntry(LinkedListNode* head) {
    LinkedListNode* slow = head;
    LinkedListNode* fast = head;
    while (fast != nullptr && fast->Next != nullptr) {
      slow = slow->Next;
      fast = fast->Next->Next;
      if (slow == fast)
