public class Solution
{
    public void SortStack(IntStack stack)
    {
        var spare = new IntStack();
        while (!stack.IsEmpty())
        {
            int value = stack.Pop();
            while (!spare.IsEmpty() && spare.Peek() > value)
                stack.Push(spare.Pop());
            spare.Push(value);
        }
        while (!spare.IsEmpty())
            stack.Push(spare.Pop());
    }
}

